import{_ as t,o as d,c as a,Q as r}from"./chunks/framework.48927342.js";const b=JSON.parse('{"title":"餐厅厨师求职邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/07-chef-job-application.md","filePath":"zh/more/maltese/practice/emails/07-chef-job-application.md"}'),e={name:"zh/more/maltese/practice/emails/07-chef-job-application.md"},o=r('<h1 id="餐厅厨师求职邮件" tabindex="-1">餐厅厨师求职邮件 <a class="header-anchor" href="#餐厅厨师求职邮件" aria-label="Permalink to &quot;餐厅厨师求职邮件&quot;">​</a></h1><p><strong>场景：</strong> 申请人写信给餐厅经理，申请餐厅的厨师职位。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a><strong>Mingħand（发件人 From）：</strong> [isem]@email.com <strong>Data（日期）：</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Applikazzjoni ta&#39; xogħol ta&#39; kok</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a><strong>Mingħand:</strong> [isem]@email.com <strong>Data:</strong> 15 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Applikazzjoni ta&#39; xogħol ta&#39; kok</p><p>Għażiż Sinjur / Sinjura,</p><p>Qed nikteb biex napplika għall-impjieg ta&#39; kok fir-ristorant tagħkom.</p><p>Għandi ħames snin esperjenza fil-kċina.</p><p>Naf insajjar platti tradizzjonali Maltin u Mediterranji.</p><p>Jien bniedem li jaħdem iebes u jimpurtani mill-kwalità tal-ikel.</p><p>Naħdem ukoll tajjeb ma&#39; tim.</p><p>Nixtieq niltaqgħa miegħkom għal intervista meta jkun konvenjenti.</p><p>Grazzi ħafna talli qiesu l-applikazzjoni tiegħi.</p><p>Nispera li nisma&#39; mingħandkom dalwaqt.</p><p>Tislijiet, [Ismek]</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></p><p><strong>整句：</strong> 收件人（To）：info@restorant.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:info@restorant.com" target="_blank" rel="noreferrer">info@restorant.com</a></td><td>邮箱地址</td><td>餐厅的招聘邮箱（示例）</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: [isem]@email.com</p><p><strong>整句：</strong> 发件人（From）：[你的名字]@email.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td>[isem]@email.com</td><td>邮箱地址</td><td>你的邮箱占位，请替换为真实邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 15 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 15 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>15</td><td>十五</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Applikazzjoni ta&#39; xogħol ta&#39; kok</p><p><strong>整句：</strong> 主题：厨师职位申请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Applikazzjoni</td><td>申请</td><td>阴性名词，借词 application</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>xogħol</td><td>工作；职位</td><td>阳性名词</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属连接词</td></tr><tr><td>kok</td><td>厨师</td><td>阳性名词，借词 cook</td></tr></tbody></table><p><strong>Malti:</strong> Għażiż Sinjur / Sinjura,</p><p><strong>整句：</strong> 亲爱的先生 / 女士：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiż</td><td>亲爱的</td><td>阳性单数形式</td></tr><tr><td>Sinjur</td><td>先生</td><td>阳性名词</td></tr><tr><td>/</td><td>或</td><td>表示二选一</td></tr><tr><td>Sinjura</td><td>女士</td><td>阴性名词</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Qed nikteb biex napplika għall-impjieg ta&#39; kok fir-ristorant tagħkom.</p><p><strong>整句：</strong> 我写信是为了申请你们餐厅的厨师职位。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Qed</td><td>正在（进行时标记）</td><td>与动词连用表示正在做某事</td></tr><tr><td>nikteb</td><td>我写</td><td>第一人称单数现在时</td></tr><tr><td>biex</td><td>为了</td><td>引出目的状语</td></tr><tr><td>napplika</td><td>我申请</td><td>第一人称单数形式，借词 apply</td></tr><tr><td>għall-impjieg</td><td>申请职位</td><td><code>għal</code>“为了” + <code>l-impjieg</code>“职位”缩合</td></tr><tr><td>ta&#39;</td><td>……的</td><td>所属/类别连接词</td></tr><tr><td>kok</td><td>厨师</td><td>阳性名词，借词 cook</td></tr><tr><td>fir-ristorant</td><td>在餐厅</td><td><code>f&#39;</code>“在” + <code>ir-ristorant</code> 缩合</td></tr><tr><td>tagħkom</td><td>你们的</td><td>复数所有格代词</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Għandi ħames snin esperjenza fil-kċina.</p><p><strong>整句：</strong> 我有五年的厨房经验。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għandi</td><td>我有</td><td><code>għand</code>“有”的第一人称单数形式</td></tr><tr><td>ħames</td><td>五</td><td>数词，后接复数名词</td></tr><tr><td>snin</td><td>年</td><td><code>sena</code>“年”的复数形式</td></tr><tr><td>esperjenza</td><td>经验</td><td>阴性名词</td></tr><tr><td>fil-kċina</td><td>在厨房</td><td><code>f&#39;</code> + <code>il-kċina</code> 缩合</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Naf insajjar platti tradizzjonali Maltin u Mediterranji.</p><p><strong>整句：</strong> 我会做传统的马耳他和地中海菜肴。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Naf</td><td>我知道；我会</td><td>第一人称单数形式</td></tr><tr><td>insajjar</td><td>我烹饪</td><td>第一人称单数现在时</td></tr><tr><td>platti</td><td>菜肴</td><td><code>platt</code>“盘子/菜”的复数</td></tr><tr><td>tradizzjonali</td><td>传统的</td><td>形容词</td></tr><tr><td>Maltin</td><td>马耳他的</td><td><code>Malti</code> 的复数形式</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>Mediterranji</td><td>地中海的</td><td>形容词复数形式</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> Jien bniedem li jaħdem iebes u jimpurtani mill-kwalità tal-ikel.</p><p><strong>整句：</strong> 我是一个努力工作并且在意食物质量的人。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Jien</td><td>我</td><td>第一人称单数代词</td></tr><tr><td>bniedem</td><td>人</td><td>阳性名词</td></tr><tr><td>li</td><td>……的；引出关系从句</td><td>关系代词</td></tr><tr><td>jaħdem</td><td>他工作</td><td>第三人称阳性单数</td></tr><tr><td>iebes</td><td>努力地；刻苦的</td><td>此处作副词“努力地”</td></tr><tr><td>u</td><td>和</td><td>连词</td></tr><tr><td>jimpurtani</td><td>我在意</td><td><code>jimpurta</code> + <code>-ni</code>“我”，惯用表达</td></tr><tr><td>mill-kwalità</td><td>关于质量</td><td><code>minn</code>“从/关于” + <code>il-kwalità</code> 缩合</td></tr><tr><td>tal-ikel</td><td>食物的</td><td><code>ta&#39;</code> + <code>l-ikel</code> 缩合</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Naħdem ukoll tajjeb ma&#39; tim.</p><p><strong>整句：</strong> 我也能和团队很好地合作。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Naħdem</td><td>我工作</td><td>第一人称单数现在时</td></tr><tr><td>ukoll</td><td>也；同样</td><td>副词</td></tr><tr><td>tajjeb</td><td>好；很好</td><td>此处作副词</td></tr><tr><td>ma&#39;</td><td>和；与</td><td>介词</td></tr><tr><td>tim</td><td>团队</td><td>阳性名词，借词 team</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Nixtieq niltaqgħa miegħkom għal intervista meta jkun konvenjenti.</p><p><strong>整句：</strong> 我希望在你们方便的时候进行面试。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nixtieq</td><td>我想要；我希望</td><td>礼貌表达愿望</td></tr><tr><td>niltaqgħa</td><td>我见面</td><td>第一人称单数形式</td></tr><tr><td>miegħkom</td><td>和你们</td><td><code>miegħ</code>“和” + <code>-kom</code>“你们”</td></tr><tr><td>għal</td><td>为了</td><td>介词</td></tr><tr><td>intervista</td><td>面试</td><td>阴性名词，借词 interview</td></tr><tr><td>meta</td><td>当……时候</td><td>连词</td></tr><tr><td>jkun</td><td>会是</td><td>第三人称单数，与 <code>konvenjenti</code> 连用</td></tr><tr><td>konvenjenti</td><td>方便的</td><td>形容词</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi ħafna talli qiesu l-applikazzjoni tiegħi.</p><p><strong>整句：</strong> 非常感谢你们考虑我的申请。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>ħafna</td><td>很；非常</td><td>程度副词</td></tr><tr><td>talli</td><td>因为（你们）……</td><td>引出原因的书面表达</td></tr><tr><td>qiesu</td><td>他们考虑了</td><td><code>qies</code>“考虑/看”的第三人称复数过去时</td></tr><tr><td>l-applikazzjoni</td><td>申请</td><td>阴性名词，带定冠词</td></tr><tr><td>tiegħi</td><td>我的</td><td>所有格代词</td></tr></tbody></table><h3 id="_8" tabindex="-1">8. <a class="header-anchor" href="#_8" aria-label="Permalink to &quot;8.&quot;">​</a></h3><p><strong>Malti:</strong> Nispera li nisma&#39; mingħandkom dalwaqt.</p><p><strong>整句：</strong> 我希望很快收到你们的回复。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nispera</td><td>我希望</td><td>第一人称单数形式</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>nisma&#39;</td><td>我听到；我收到消息</td><td>第一人称单数形式</td></tr><tr><td>mingħandkom</td><td>从你们那里</td><td><code>mingħand</code>“从……那里” + <code>-kom</code>“你们”</td></tr><tr><td>dalwaqt</td><td>很快</td><td>副词，<code>dal-</code>“这个” + <code>waqt</code>“时刻”</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, [Ismek]</p><p><strong>整句：</strong> 此致敬意，[你的名字]（正式邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Ismek</td><td>你的名字</td><td><code>isem</code>“名字” + <code>-ek</code>“你的”；请替换为真实姓名</td></tr></tbody></table>',57),i=[o];function n(l,h,s,p,c,m){return d(),a("div",null,i)}const k=t(e,[["render",n]]);export{b as __pageData,k as default};
